"""Narrative text per block: what the data does inside. Numbers match the frozen contract and sheets."""
T = {}
T['clk_rst_gen'] = dict(purpose='Produces the single clock and the single reset of the whole SoC.',
 steps=['clk_in is passed unchanged to clk (a wire; the FPGA tool adds the global buffer). There is no second clock anywhere.',
        'rst_n_in (asynchronous, may bounce) and pll_locked_i are combined: rst_ok = rst_n_in AND pll_locked_i. If rst_ok is 0 the rst_n flop is cleared ASYNCHRONOUSLY, i.e. rst_n falls at once. This is the only asynchronous reset in the design.',
        'When rst_ok returns to 1, a 2-flop synchroniser re-times it to clk, so release is synchronous.',
        'A power-on hold counter then counts 255 clk cycles (5.1 us). Any new low on rst_ok restarts it, so a bouncing button can never release reset early.',
        'When the hold finishes, rst_n goes high on a clk edge. Release happens 255 + 2 = 257 cycles after the last rising edge of rst_ok.'],
 timing='assert: 0 cycles (asynchronous); release: 257 cycles = 5.14 us after the last bounce',
 fpga='pll_locked_i comes from the FPGA clock generator (tie 1 if there is none). In the GDSII it is the lock of a PLL macro, or tied 1 with an external 50 MHz clock pad. The rest is identical.',
 verify='bounce test (low 3, high 1, low 2, high): rst_n stays low for the whole sequence and releases 257 cycles after the final high; pll_locked_i = 0 holds reset. Testbench rule for Ibex (ACR-5): start rst_n high and pull it low after time 0.')
T['timer_unit'] = dict(purpose='The heartbeat: one control_tick pulse every TICK_PERIOD clk cycles (about 512 Hz) starts every sample; a slow interrupt serves the CPU.',
 steps=['CPU writes land in tmr_regs (EN, IRQ_EN, TICK_PERIOD, IRQ_DIV). Reset values: EN = DEF_EN, TICK_PERIOD = 97656, IRQ_DIV = 51.',
        'cycle_counter counts 0 ... TICK_PERIOD-1 on every clk while EN = 1. A new TICK_PERIOD written mid-run is only loaded at the wrap, so there is never a short or long glitch period.',
        'At the wrap, tick_gen emits control_tick_o: a registered pulse exactly 1 clk wide (1.953 ms apart at the default).',
        'Each tick increments tick_counter (TICK_COUNT) and clocks irq_divider. free_counter (32-bit) runs on every clk independently and is the timestamp FREE_CNT.',
        'After IRQ_DIV ticks, irq_pending sets. irq_timer_o = irq_pending AND IRQ_EN, a LEVEL that stays high until the CPU writes 1 to STATUS.IRQ_PENDING (W1C).',
        'overrun_detect: at every tick, if sched_busy_i (imu_busy) is still high, STATUS.OVERRUN sets (sticky, W1C): the I2C read of the previous sample did not finish within one period.'],
 timing='97656 cycles = 1.953 ms tick; 51 ticks = 99.6 ms interrupt. The register minimum is 1000 cycles, but because the I2C burst needs about 20,000 cycles (0.4 ms) a practical floor is about 25,000 cycles. EN = 0: no ticks, no interrupt. Counters restart on EN rising or CNT_CLR.',
 fpga='nothing FPGA-specific. DEF_EN follows HW_ONLY.', verify='TICK_PERIOD = 100: ten pulses exactly 100 clk apart, width 1; change period mid-run; IRQ_DIV = 3; hold sched_busy_i high at a tick; EN = 0.')
T['i2c_sensor_subsystem'] = dict(purpose='Reads the MPU-6050 over I2C on every control_tick and publishes one coherent 6-axis sample.',
 steps=['After reset, once EN = 1 (or DEF_EN), mpu6050_ctrl waits about 50 ms, reads WHO_AM_I (0x75, expects 0x68), then writes PWR_MGMT_1 (0x6B) = 0x01 (the chip powers up asleep), SMPLRT_DIV (0x19) = 0x00, CONFIG (0x1A) = 0x02, GYRO_CONFIG (0x1B) = 0x00, ACCEL_CONFIG (0x1C) = 0x00. Then imu_init_done_o goes high (ACR-7: it is low during any (re-)initialisation).',
        'On every control_tick_i (ignored while busy) the sequencer raises imu_busy_o and issues: START, addr+W, register 0x3B, repeated START, addr+R, 14 byte reads (ACK the first 13, NACK the 14th), STOP.',
        'i2c_master turns each command into bit activity. The clock divider makes four phases per SCL period: f_scl = 50 MHz / (4 x (CLK_DIV + 1)) = 390.6 kHz at CLK_DIV = 31 (one bit 2.56 us, one byte 23 us). SDA/SCL are only ever pulled low or released (scl_drive_low_o, sda_drive_low_o); the inputs scl_i and sda_i pass through 2-flop synchronisers; clock stretching is honoured by waiting until scl_i is really high.',
        'Received bytes (high byte first) go to sample_assembler: ax = {b0,b1}, ay = {b2,b3}, az = {b4,b5}, temperature {b6,b7} discarded, gx = {b8,b9}, gy = {b10,b11}, gz = {b12,b13}.',
        'Only after the STOP condition are all six values copied together into imu_*_o and the AX...GZ registers, SAMPLE_COUNT increments, imu_valid_o pulses and imu_busy_o falls. A half-updated sample is never visible.',
        'Errors: a NACK, or a transaction longer than 1.5 ms, aborts, sends STOP, pulses imu_err_o, increments ERR_COUNT and sets ERR_STICKY (or TIMEOUT_STICKY); the sample is skipped. A stuck SDA gets 9 SCL pulses then STOP. Three consecutive errors re-run the init sequence.'],
 timing='control_tick_i to imu_valid_o: 380-440 us (156 SCL periods x 128 cycles = 19,968 cycles = 0.399 ms). Model values ax=0x1000, ay=0xF000, az=0x4000, gx=0x0083, gy=0xFF00, gz=0 give 4096, -4096, 16384, 131, -256, 0.',
 fpga='the open-drain pad (scl_pad, sda_pad) is made in ecu_fpga_top with an IOBUF and 4.7 kOhm pull-ups to 3.3 V; in the GDSII it is an open-drain pad cell. This block only produces drive_low and reads the synchronised pin level.',
 verify='behavioural MPU-6050 model with 128-byte register file, repeated start, auto-increment, sleep bit, NACK and clock-stretch injection; latency window; REINIT; stuck-bus recovery.')
T['sensor_pipeline'] = dict(purpose='Turns raw IMU counts into the angle, rate and error the PID consumes, using only shifts and adds.',
 steps=['imu_valid_i: meas_capture latches all six raw axes in the SAME cycle (coherent sample) and increments SEQ_COUNT.',
        'Calibration FSM IDLE -> SETTLE -> ACCUM -> DONE. It starts on CAL_START, or automatically on the rising edge of imu_init_done_i if DEF_EN = 1. SETTLE discards 64 samples; ACCUM adds gx, gy, gz of 256 samples into three 24-bit accumulators; bias = sum >>> 8 (readable in GYRO_BIAS_X/Y/Z); calib_done_o = 1. From then on gyro = sat16(raw - bias). During calibration data keeps flowing uncorrected.',
        'angle_conv: AXIS_SEL = 0 uses accel X and gyro Y, AXIS_SEL = 1 uses accel Y and gyro X. angle = accel x 4 (Q16.16 rad, e.g. 4096 -> 16384). rate = (g<<3) + (g>>>1) + (g>>>2) = 8.75 x g (131 -> 1145). INV_ANGLE / INV_RATE negate. Latency 1 cycle.',
        'sensor_filter: two moving_avg_filter instances (32-bit), one for angle and one for rate. N = 2^k from FILT_SHIFT (reset 0x22 = k 2 for both; k = 0 bypasses). Circular buffer of N samples with running sum: sum = sum + new - oldest; out = sum >>> k. Changing k clears buffer and sum. Optional complementary filter (FILT_MODE = 1): pred = angle_f + (rate >>> 9); angle_f = pred - (pred >>> 6) + (angle_acc >>> 6).',
        'trim: angle_o = filtered angle - ANGLE_TRIM (the trim is subtracted after the filter).',
        'error_calc: err_o = setpoint_i - angle_o (saturating 32-bit). rate passes through. One pulse pipe_valid_o is emitted with angle_o, err_o and rate_o all valid in that cycle.',
        'Telemetry registers record ANGLE_RAW (after conversion), ANGLE_FILT, RATE_FILT, ERROR, SEQ_COUNT. STATUS.DATA_FRESH sets with every pipe_valid_o and clears if no sample arrived within 2 control_tick_i (ACR-2).'],
 timing='imu_valid_i to pipe_valid_o <= 64 cycles (about 6-8 in practice). Filter delay (N-1)/2 samples = about (N-1) ms at 512 Hz, on top of the MPU-6050 low-pass (about 3 ms).',
 fpga='nothing FPGA-specific; DEF_EN follows HW_ONLY (auto-calibration).', verify='angle_conv, moving_avg, error_calc and calibration vectors; 1000 random samples against model/sensor_pipeline.py with zero differences; exactly one pipe_valid_o per imu_valid_i.')
T['hw_pid_accel'] = dict(purpose='Hardware PID: u = Kp*e + Ki*Ts*sum(e) - Kd*rate in Q16.16, one shared multiplier, at most 16 cycles.',
 steps=['err_valid_i (pipe_valid): the input gate captures err_i and rate_i. If run_i = 0 or EN = 0 the output is forced to 0, the integrator is cleared, e_prev = e (no derivative kick on re-enable) and pwm_cmd_valid_o still pulses (value 0) so actuation sees zero commands.',
        'pid_fsm steps IDLE -> P -> I -> D -> SUM -> OUT (about 8 cycles) and time-shares one signed 32x32 -> 64 bit multiplier; every product is (a*b) >>> 16.',
        'P = Kp*e. I: acc += Ki*e (Ki already holds Ki*Ts); clamp to +-INT_LIMIT; freeze while the summed output is already clamped in the direction of the error. D: with D_SRC = 1, D = -(Kd*rate) >>> 16 (because error = setpoint - angle, d(error)/dt = -rate); with D_SRC = 0, D = Kd*(e - e_prev) (Kd must then be pre-divided by Ts).',
        'SUM adds P + I + D in 34 bits. The result is clamped to +-OUT_LIMIT (maximum 65536); SAT = 1 if it was clamped. pwm_cmd_o = result and pwm_cmd_valid_o pulses.',
        'The SETPOINT register value is driven continuously on setpoint_o to sensor_pipeline. Telemetry: P_TERM, I_TERM, D_TERM, U_OUT; STATUS.SAT (live), SAT_STICKY (W1C), ACTIVE.'],
 timing='err_valid_i to pwm_cmd_valid_o <= 16 cycles (0.32 us). Sign rule: leaning forward => angle > 0 => err < 0 => u < 0; the motor direction bits must make u < 0 drive the wheels forward. Vectors: Kp = 65536, e = 6554 -> u = 6554; Kp = 524288, e = 13107, OUT_LIMIT 16384 -> clamped, sat = 1.',
 fpga='nothing FPGA-specific; DEF_EN, DEF_KP... follow HW_ONLY (no CPU: defaults must already balance the robot).', verify='7 directed vectors, 1000 random vectors against model/pid.py bit-for-bit, closed-loop pendulum model.')
T['actuation_subsystem'] = dict(purpose='Turns the PID command into safe PWM for two BTS7960 drivers.',
 steps=['On cmd_valid_i the source is chosen: if bench_en_i (synchronised, bring-up only) the bench table is used (00 -> 0, 01 -> +16384, 10 -> -16384, 11 -> +32768), else cmd_i.',
        'steer_gain: left_raw = cmd + steer and right_raw = cmd - steer, each multiplied by GAIN_L / GAIN_R ((a*b) >>> 16).',
        'clamp: each channel limited to +-65536 (+-1.0) when CLAMP_EN = 1; STATUS.CLAMPED sets.',
        'slew limiter (SLEW_EN): the value moves toward the target by at most SLEW_STEP (6554 = 0.1) per update; when pwm_enable_i rises it starts from 0, so full scale takes 10 updates (about 19.5 ms).',
        'Per channel: mag16 = min(|cmd|, 65535), then min(mag16, MAX_DUTY); duty_counts = (mag16 x PERIOD) >> 16 (cmd 0.5 -> 1250 of 2500; MAX_DUTY 0.9 -> 2249).',
        'Direction: cmd > 0 drives RPWM, cmd < 0 drives LPWM, DIR_INV_x swaps them. The dead-time FSM (RUN_FWD, RUN_REV, DEAD) holds both outputs low for DEADTIME = 250 cycles (5 us) on every reversal. RPWM and LPWM are NEVER high together.',
        'The PWM core counts 0 ... PERIOD-1 and is high while count < duty_counts. Duty and direction are latched at the period wrap (double-buffered), so no runt pulses.',
        'enable_gate: every *_EN pin = pwm_enable_i AND EN. When 0, both PWM outputs and all four enables are low within 2 clk. Bench mode is still gated by pwm_enable_i.'],
 timing='cmd_valid_i to the next PWM period wrap <= 1 period (50 us); PERIOD 2500 cycles = 20 kHz. Vectors: cmd +32768 -> duty 1250; cmd +131072 -> clamped, duty 2499; steer 6554, cmd 32768 -> left 1500, right 999.',
 fpga='bench_en_i / bench_sel_i are bring-up only (tie 0 in the GDSII). duty_l_o / duty_r_o are debug taps. Synchronisers for the bench pins are inside this block (ACR-1).',
 verify='13 vectors; assertion !(rpwm && lpwm) on every clock for the whole simulation; scope check of 20 kHz and duty.')
T['safety_fault_monitor'] = dict(purpose='Decides whether the motors may move. Fail-safe: any doubt makes pwm_enable_o = 0 within 2 clk, faults latch, re-arming is deliberate.',
 steps=['input_sync passes estop_n_i and arm_sw_i through 2 flops each (ACR-1).',
        'Detectors, evaluated only while ARMED (the E-stop always latches): TILT = |angle_i| > TILT_LIMIT on 3 consecutive pipe_valid_i (if TILT_EN); SENSOR_TIMEOUT = no imu_valid_i for SENSOR_TIMEOUT consecutive control_tick_i; I2C_ERR = 3 consecutive imu_err_i (cleared by imu_valid_i); PID_SAT = pid_sat_i high for SAT_LIMIT consecutive pipe_valid_i; WATCHDOG = no WD_KICK write for WD_TIMEOUT ticks (if WD_EN); ESTOP = synchronised estop_n_i low, immediate, from any state.',
        'fault_flags keeps sticky bits in FAULT_STATUS (bit 0 TILT, 1 SENSOR_TIMEOUT, 2 I2C_ERR, 3 PID_SAT, 4 WATCHDOG, 5 ESTOP); FAULT_LIVE shows the live conditions.',
        'arm_fsm: arm_req = ARM | synchronised arm_sw_i. DISARMED -> ARMED when arm_req AND calib_done_i AND no live fault AND flags == 0. Any fault: ARMED -> FAULT. FAULT -> DISARMED only after FAULT_CLR (condition gone) and arm_req low; then ARM low-to-high arms again. A robot never restarts by itself.',
        'pwm_enable_o is a registered output: 1 only in ARMED, 0 within 2 clk of any fault (3 clk from the E-stop pin). It never depends on a CPU action to turn OFF.',
        'irq_fault_o = IRQ_EN AND (any sticky flag): a level, cleared by clearing the flags. dbg_o[3:0] = {calib_done_i, imu_init_done_i, fault_any, pwm_enable_o}; dbg_o[7:4] = DBG_OUT[7:4].'],
 timing='fault to pwm_enable_o low <= 2 clk; E-stop <= 3 clk. Reset: DISARMED, pwm_enable_o = 0, CTRL = 0x04 (TILT_EN = 1; ACR-3). Watchdog off by default (phase 1 has no CPU).',
 fpga='arm_sw_i is bring-up only (tie 0 in the GDSII); dbg_o drives LEDs on the FPGA and spare pins (or nothing) in the GDSII.', verify='14 scenarios: reset, arm without calibration, tilt debounce (3 vs 2 samples), sensor time-out, I2C errors (3 vs 2), saturation, watchdog, E-stop while disarmed, clear while condition live, re-arm sequence, two faults at once.')
T['bus_interconnect'] = dict(purpose='Connects Ibex to the memories and the six register banks. Zero wait states; every address gets an answer.',
 steps=['Instruction side: instr_gnt_o = instr_req_i (same cycle). Only ROM is fetchable: rom_ia_req_o and rom_ia_addr_o[12:0] drive the ROM instruction port; one cycle later instr_rvalid_o = 1 with instr_rdata_o = rom_ia_rdata_i. A fetch outside ROM returns instr_rvalid_o with instr_err_o = 1.',
        'Data side: data_gnt_o = data_req_i (same cycle). The address decoder compares the top address bits: ROM window addr[31:13] == 0; bank n addr[31:12] == 0x10000 + n; RAM addr[31:12] == 0x20000; anything else is unmapped.',
        'The select / write-enable / byte-enable / address / write-data signals fan out to the 8 targets; the selects are one-cycle pulses aligned with the request.',
        'sel_q registers the decoded select (and the error flag). One cycle later the read-data mux outputs the REGISTERED read data of the selected slave on data_rdata_o together with data_rvalid_o = 1. Writes also get data_rvalid_o (Ibex waits for it).',
        'error responder: an unmapped address, or a write to ROM, returns data_rvalid_o with data_err_o = 1, selects no slave and causes no side effect. No access may ever hang the CPU. Ibex turns the error into exception cause 1, 5 or 7 at vector offset 0x00.'],
 timing='grant: same cycle; response: next cycle; a load or store therefore takes at least 2 cycles in Ibex.', fpga='nothing FPGA-specific.',
 verify='7 vectors: RAM word and byte write; read the six IDs; unmapped read; write to ROM; 3 back-to-back reads of different targets; instruction fetch from ROM and from RAM (error); acceptance = real Ibex reads all six IDs (tb_cpu_bus: PASS).')
T['rom_dp'] = dict(purpose='8 KB firmware ROM with two independent read ports.',
 steps=['Port A (instruction side): when ia_req_i is high, the word at ia_addr_i[12:2] is registered into ia_rdata_o (valid the next cycle).',
        'Port B (data side): when s_sel_i is high, the word at s_addr_i[12:2] is registered into s_rdata_o (constants and .rodata).',
        'The array has 2048 x 32 bits and is loaded with $readmemh(INIT_FILE = "firmware.hex") at simulation / FPGA configuration. There is no write port: a store to ROM never arrives (the bus answers it with an error).'],
 timing='registered reads: one cycle', fpga='$readmemh initialisation and BRAM inference are FPGA/simulation features; in the GDSII the ROM is a macro or mask ROM and firmware.hex becomes its programming file.', verify='two ports read different addresses in the same cycle; word at 0x80; read latency one cycle.')
T['ram_sp'] = dict(purpose='4 KB data RAM with byte write enables (compilers emit sb and sh).',
 steps=['When s_sel_i and s_we_i are high, each byte lane i of word s_addr_i[11:2] is written if s_be_i[i] = 1.',
        'When s_sel_i is high, the addressed word is registered into s_rdata_o (valid the next cycle). Read during write to the same address returns the new data on the next read (documented behaviour).'],
 timing='registered read: one cycle', fpga='block RAM inference; in the GDSII an SRAM macro or a flop array (area decision of the layout phase; 12 KB of memory dominates the area).', verify='word write; byte write 0xAA at be 0001; halfword write at be 1100; read latency exactly one cycle.')
T['cpu_subsystem'] = dict(purpose='Ibex RV32IMC (small configuration) with every unused port tied off. It supervises; it is never in the real-time loop.',
 steps=['After reset (async inside Ibex) the first instruction is fetched from boot_addr 0x0 + 0x80 through the instruction port; the bus answers from ROM.',
        'IF stage: program counter, prefetch buffer, compressed-instruction expander. ID/EX stage: decoder, controller, ALU, multiplier/divider and the load/store unit. 32 registers in flip-flops.',
        'Loads and stores leave on the data port (data_req_o, data_we_o, data_be_o, data_addr_o, data_wdata_o) and stall the pipeline until data_rvalid_i; a bus error becomes exception cause 5 (load) or 7 (store).',
        'irq_timer_i (machine timer, mcause 7) jumps to vector 0x1C and irq_fault_i (machine external, mcause 11) to vector 0x2C once the interrupt is enabled in mie and mstatus.MIE; all interrupts are off after reset and the lines are level-sensitive.',
        'Tie-offs: test_en_i = 0, scan_rst_ni = 1, hart_id_i = 0, fetch_enable_i = on (MuBi), mcounteren_writable_i = on, debug_req_i = 0, irq_software / irq_fast / irq_nm = 0, CHERIoT off, integrity and scrambling inputs 0. Outputs core_sleep_o and double_fault_seen_o are debug taps.'],
 timing='load/store >= 2 cycles; multiply 3; divide 38; first fetch at 0x80.', fpga='RegFileFF (or RegFileFPGA) and a pass-through prim_clock_gating on the FPGA; RegFileLatch and a real clock-gating cell are options for the GDSII; test_en_i / scan_rst_ni become scan connections in the layout flow.',
 verify='tb_cpu_bus with the real Ibex: ID read test, RAM test, timer-interrupt test and the full application were run (all PASS); lint of the wrapper against the pinned Ibex commit af456e2: 0 warnings.')
T['ecu_soc_top'] = dict(purpose='The SoC top: instantiates and wires the 11 RTL blocks exactly as the netlist; no logic of its own.',
 steps=['Parameter HW_ONLY (default 0). HW_ONLY = 1 passes DEF_EN = 1 to timer_unit, i2c_sensor_subsystem, sensor_pipeline, hw_pid_accel, actuation_subsystem and safety_fault_monitor, so Wing A runs with no CPU (FPGA phase 1). DEF_WD_EN stays 0.',
        'Wing A (real-time): i2c -> sensor_pipeline -> hw_pid_accel -> actuation, with control_tick from the timer and pwm_enable from the safety monitor.',
        'Wing B (supervisory): cpu_subsystem <-> bus_interconnect <-> rom_dp, ram_sp and the six register banks; irq_timer and irq_fault return to the CPU.',
        'The 20 top-level pins are raw: the SoC itself synchronises them (ACR-1).'],
 timing='worst-case tick-to-motor path 22,550 cycles (0.451 ms) in a 97,656-cycle tick: margin 1.50 ms.', fpga='HW_ONLY, arm_sw_i, bench_en_i, bench_sel_i, dbg_o and pll_locked_i are FPGA / bring-up items (see the FPGA-only table).', verify='lint with Verilator -Wall: 0 warnings (generated skeleton and with the real Ibex wrapper); netlist checker: 36 checks pass.')
T['ecu_fpga_top'] = dict(purpose='FPGA-only board wrapper; replaced by the pad ring in the GDSII.',
 steps=['fpga_clk_gen (MMCM) turns the 100 MHz board oscillator into exactly 50 MHz and a locked signal: clk_in and pll_locked_i of ecu_soc_top.',
        'The open-drain pad logic drives scl_pad / sda_pad low or lets them float (external pull-ups) and returns the pin levels as scl_i / sda_i.',
        'All other pins (reset, E-stop, arm, bench, motor pins, LEDs) go straight through buffers; there are NO synchronisers here (ACR-1).',
        'Instantiates ecu_soc_top with HW_ONLY (1 for the phase-1 bitstream, 0 for the final).'],
 timing='n/a', fpga='the whole block is FPGA-only.', verify='pin table and XDC; clock constraint 20 ns; scope the PWM pins with the motor supply disconnected before connecting motors.')
T['firmware'] = dict(purpose='C program in ROM that configures and supervises the hardware through the register banks.',
 steps=['startup.S: vector table at 0x00-0x7F (exceptions at 0x00, timer 0x1C, external 0x2C), reset jump at 0x80, stack pointer = 0x2000_1000, copy .data, clear .bss, mtvec, call main.',
        'main.c boot: read the six ID words; configure the timer; enable I2C and wait INIT_DONE; set the pipeline bits and start calibration; load Kp, Ki*Ts, Kd, setpoint and limits; configure PWM; set the safety thresholds, enable watchdog and fault interrupt; enable interrupts; ARM.',
        'Loop: on the timer heartbeat kick the watchdog and read telemetry; on a fault report read FAULT_STATUS and stay disarmed.',
        'Rules: volatile 32-bit register access, time-out on every wait, interrupt handlers never read-modify-write peripheral registers.'],
 timing='boot-and-configure sequence is about 250 instructions (252 words of code).', fpga='firmware.hex is the ROM initialisation file.', verify='software model: tests 0, 1, 2, 4 pass and the application makes 32 register writes; real Ibex testbench: tests 0, 1, 3 and the application (same 32 writes).')
